const star5 = (cx, cy, R, r, rot = -90) => { const o = []; for (let i = 0; i < 10; i++) { const a = (rot + i * 36) * DEG, q = i % 2 ? r : R; o.push([cx + Math.cos(a) * q, cy + Math.sin(a) * q]); } return o; };
