    ctx.fillStyle = '#000000';
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(cw, 0); ctx.lineTo(cw, h - bow); ctx.quadraticCurveTo(cw / 2, h + bow, 0, h - bow); ctx.closePath(); ctx.fill();
