    const e = E.outCubic(clamp(bgT(env) / 0.3)), rx = W * (P.clear || 0.38) * (1 + (1 - e) * 0.6), ry = H * (P.clear || 0.38) * 1.05 * (1 + (1 - e) * 0.6), R = Math.hypot(W, H) * 0.6;
