      ctx.fillStyle = tintC(sc, (P.k || 0.35) * 0.45); ctx.beginPath(); ctx.arc(W / 2, sy, R * e, 0, TAU); ctx.fill();
      ctx.fillStyle = sc.bg; for (let i = 0; i < 5; i++) { const yy = sy + R * (0.1 + i * 0.18), hh = R * 0.03 * (1 + i * 0.6); ctx.fillRect(W / 2 - R, yy, R * 2, hh); }
      ctx.restore();
