    if (c <= 0.001) return;
    const L = vert ? ch : cw, half = L / 2 * c + 1, lw = Math.max(2, Math.min(cw, ch) * 0.008), col = inkOf(sc);
    const R = (a, b, w, h) => (vert ? ctx.fillRect(b, a, h, w) : ctx.fillRect(a, b, w, h));
    const M = vert ? cw : ch;
    ctx.fillStyle = col; R(0, 0, half, M); R(L - half, 0, half, M);
