    ctx.beginPath(); ctx.arc(cx, cy, r + lw / 2, 0, TAU); ctx.stroke();
    ctx.globalAlpha = a * 0.6; ctx.strokeStyle = tAcc(I, true); ctx.lineWidth = lw * 0.4;
